insert into public.briefings (briefing_date, kind, headline, body, updated_at) values
('2026-09-07', 'daily',
 'Labor Day tape — cash closed, week still loaded',
 E'US cash session is closed (Labor Day). Index futures still trade; treat overnight headlines as the open setup for Tuesday 16:30 Sofia.\nCPI (11 Sep), PPI (10 Sep) and the 16 Sep FOMC decision are the week''s high-impact prints.\nAugust payrolls printed 162,000 and flipped hike odds higher — UBS now looks for 25bp in September and December.\nOil is two-sided: Goldman flags $120 if Hormuz shipping stays disrupted; Bessent still talks $40 if supply floods back. OPEC+ holds October quotas.\nYen is at its strongest since February on BOJ hike bets. Bitcoin tagged ~$80k into the holiday with divergence warnings.',
 now()),
('2026-09-07', 'weekly',
 'Week ahead for futures',
 E'Highest-impact diary:\n- PPI YoY/MoM — 10 Sep 08:30 ET (15:30 Sofia)\n- CPI YoY/Core/MoM — 11 Sep 08:30 ET (15:30 Sofia)\n- EIA crude inventories — 9/16/23/30 Sep 10:30 ET\n- Retail Sales — 16 Sep 08:30 ET\n- FOMC rate decision + press conference — 16 Sep 14:00/14:30 ET (21:00/21:30 Sofia)\n- Core PCE — 25 Sep 08:30 ET\nWatch: Fed hike repricing after 162k payrolls, Hormuz/oil, BOJ/yen, and Tuesday''s cash reopen after Labor Day.',
 now())
on conflict (briefing_date, kind) do update
set headline = excluded.headline, body = excluded.body, updated_at = excluded.updated_at;
